182→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
183→  const { t } = useTranslation();
184→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
185→  const [isEditing, setIsEditing] = useState(false);
186→  const [editText, setEditText] = useState(message.content);
187→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
188→  const textareaRef = useRef<HTMLTextAreaElement>(null);
189→
190→  const isUser = message.role === 'user';
191→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
192→
193→  useEffect(() => {
194→    if (isEditing && textareaRef.current) {
195→      textareaRef.current.focus();
196→      textareaRef.current.selectionStart = textareaRef.current.value.length;
197→    }
198→  }, [isEditing]);
199→
200→  const handleEdit = () => {
201→    setEditText(message.content);
202→    setIsEditing(true);
203→    setIsConfirmingDelete(false);
204→  };
205→
206→  const handleCancelEdit = () => {
207→    setIsEditing(false);
208→    setEditText(message.content);
209→  };
210→
211→  const handleSaveEdit = () => {
212→    const trimmed = editText.trim();
213→    if (!trimmed || trimmed === message.content) {
214→      handleCancelEdit();
215→      return;
216→    }
217→    setIsEditing(false);
218→    editMessage(messageIndex, trimmed);
219→  };
220→
221→  const handleDeleteConfirm = () => {
222→    setIsConfirmingDelete(false);
223→    deleteMessage(messageIndex);
224→  };
225→
226→  const handleKeyDown = (e: React.KeyboardEvent) => {
227→    if (e.key === 'Escape') {
228→      handleCancelEdit();
229→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
230→      e.preventDefault();
231→      handleSaveEdit();
232→    }
233→  };
234→
235→  let streamingRemainder: string | undefined;
236→  if (hasSegments && message.isStreaming && message.content) {
237→    const segmentedText = message.segments!
238→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
239→      .map((s) => s.text || '')
240→      .join('');
241→    const remaining = message.content.slice(segmentedText.length);
242→    if (remaining.trim()) {
243→      streamingRemainder = remaining;
244→    }
245→  }
246→
247→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
248→  const isInAnswerPhase = message.currentPhase === 'answer';
249→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
250→
251→  const hasCharts = hasSegments && message.segments!.some(
252→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
253→  );
254→
255→  const answerBlockSegments = hasSegments
256→    ? message.segments!
257→        .filter((s) =>
258→          (s.type === 'answer' && s.text?.trim()) ||
259→          (s.type === 'subagent_end' && !s.chart_spec && !s.sqlResults?.length && s.text?.trim() && !hasAnswer) ||
260→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
261→          (s.type === 'subagent_end' && s.chart_spec)
262→        )
263→        .map((s) => {
264→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
265→            return { ...s, text: stripChartSpecBlocks(s.text) };
266→          }
267→          return s;
268→        })
269→        .filter((s) => {
270→          // Remove text segments that became empty after stripping chart blocks
271→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
272→            return false;
273→          }
274→          return true;
275→        })
276→    : [];
277→
278→  const questionSegments = hasSegments
279→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
280→    : [];
281→
282→  return (
283→    <div className={`message-bubble message-bubble--${message.role}`}>
284→      <div className="message-bubble__header">
285→        {isUser ? t('you') : t('assistant')}
286→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
287→          <span className="message-bubble__actions">
288→            <button
289→              className="message-bubble__action-btn"
290→              onClick={handleEdit}
291→              title={t('editMessage')}
292→            >
293→              &#9998;
294→            </button>
295→            <button
296→              className="message-bubble__action-btn message-bubble__action-btn--delete"
297→              onClick={() => setIsConfirmingDelete(true)}
298→              title={t('deleteMessage')}
299→            >
300→              &#128465;
301→            </button>
302→          </span>
303→        )}
304→      </div>
305→
306→      {isUser && isConfirmingDelete && (
307→        <div className="message-bubble__confirm-delete">
308→          <span>{t('deleteConfirm')}</span>
309→          <div className="message-bubble__confirm-actions">
310→            <button
311→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
312→              onClick={handleDeleteConfirm}
313→            >
314→              {t('delete')}
315→            </button>
316→            <button
317→              className="message-bubble__confirm-btn"
318→              onClick={() => setIsConfirmingDelete(false)}
319→            >
320→              {t('cancel')}
321→            </button>
322→          </div>
323→        </div>
324→      )}
325→
326→      {isUser && isEditing ? (
327→        <div className="message-bubble__edit-mode">
328→          <textarea
329→            ref={textareaRef}
330→            className="message-bubble__edit-textarea"
331→            value={editText}
332→            onChange={(e) => setEditText(e.target.value)}
333→            onKeyDown={handleKeyDown}
334→            rows={3}
335→          />
336→          <div className="message-bubble__edit-actions">
337→            <button
338→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
339→              onClick={handleSaveEdit}
340→            >
341→              {t('saveResend')}
342→            </button>
343→            <button
344→              className="message-bubble__edit-btn"
345→              onClick={handleCancelEdit}
346→            >
347→              {t('cancel')}
348→            </button>
349→          </div>
350→        </div>
351→      ) : hasSegments ? (
352→        <div className="message-bubble__segments">
353→          {!questionSegments.some((s) => !s.userAnswer) && (
354→            <ThinkingBlock
355→              segments={message.segments!}
356→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
357→              isThinkingPhase={isThinkingPhase}
358→              isAgentStreaming={!!message.isStreaming}
359→              hasAnswer={hasAnswer}
360→            />
361→          )}
362→          {questionSegments.map((seg, i) => (
363→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
364→              <UserQuestion
365→                questionData={seg.questionData!}
366→                userAnswer={seg.userAnswer}
367→                userFreeText={seg.userFreeText}
368→                answerDurationMs={seg.answerDurationMs}
369→              />
370→            </div>
371→          ))}
372→          {answerBlockSegments.length > 0 && (
373→            <div className="message-bubble__segment message-bubble__segment--answer">
374→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
375→              {answerBlockSegments.map((seg, i) => {
376→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
377→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
378→                  return (
379→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
380→                      {seg.type === 'tool' && seg.toolResult ? (
381→                        <InlineQueryResult result={seg.toolResult!} />
382→                      ) : seg.chart_spec ? (
383→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
384→                      ) : null}
385→                    </div>
386→                  );
387→                }
388→                // Text segment (answer or subagent_end without chart_spec)
389→                return (
390→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
391→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(seg.text!)}</ReactMarkdown>
392→                  </div>
393→                );
394→              })}
395→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
396→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
397→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
398→                return displayText?.trim() ? (
399→                  <div className="message-bubble__segment-content">
400→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
401→                  </div>
402→                ) : null;
403→              })()}
404→              {!message.isStreaming && message.durationMs != null && (
405→                <div className="message-bubble__duration">
406→                  {t('answeredIn', { time: formatDuration(message.durationMs) })}
407→                </div>
408→              )}
409→            </div>
410→          )}
411→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
412→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
413→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
414→            return displayText?.trim() ? (
415→              <div className="message-bubble__segment message-bubble__segment--answer">
416→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
417→                <div className="message-bubble__segment-content">
418→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
419→                </div>
420→              </div>
421→            ) : null;
422→          })()}
423→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
424→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
425→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
426→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
427→          })}
428→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
429→            <span className="message-bubble__typing">{t('thinking')}</span>
430→          )}
431→        </div>
432→      ) : (
433→        <>
434→          <div className="message-bubble__content">
435→            {message.content ? (
436→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(message.content)}</ReactMarkdown>
437→            ) : message.isStreaming ? (
438→              <span className="message-bubble__typing">{t('thinking')}</span>
439→            ) : null}
440→          </div>
441→          {message.toolCalls && message.toolCalls.length > 0 && (
442→            <div className="message-bubble__tools">
443→              {message.toolCalls.map((tc) => (
444→                <InlineQueryResult key={tc.toolCallId} result={tc} />
445→              ))}
446→            </div>
447→          )}
448→        </>
449→      )}
450→    </div>
451→  );
452→}
